CREATE TABLE IF NOT EXISTS `#__joomleague_stage_transition` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `uuid` CHAR(36) NOT NULL, `project_id` BIGINT UNSIGNED NOT NULL, `source_stage_id` BIGINT UNSIGNED NOT NULL, `target_stage_id` BIGINT UNSIGNED NOT NULL,
  `code` VARCHAR(100) NOT NULL, `name` VARCHAR(255) NOT NULL, `selector_type` VARCHAR(100) NOT NULL, `selector_config_json` LONGTEXT NULL, `carry_over_mode` VARCHAR(100) NOT NULL DEFAULT 'none', `target_seed_start` INT UNSIGNED NULL DEFAULT NULL,
  `published` TINYINT NOT NULL DEFAULT 1, `ordering` INT NOT NULL DEFAULT 0, `created` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `created_by` BIGINT UNSIGNED NOT NULL DEFAULT 0, `modified` DATETIME NULL DEFAULT NULL, `modified_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_jl_stage_transition_uuid` (`uuid`), UNIQUE KEY `uq_jl_stage_transition_code` (`project_id`, `code`), KEY `idx_jl_stage_transition_source` (`source_stage_id`, `project_id`, `published`, `ordering`), KEY `idx_jl_stage_transition_target` (`target_stage_id`, `project_id`),
  CONSTRAINT `fk_jl_stage_transition_project` FOREIGN KEY (`project_id`) REFERENCES `#__joomleague_project` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_jl_stage_transition_source` FOREIGN KEY (`source_stage_id`, `project_id`) REFERENCES `#__joomleague_project_stage` (`id`, `project_id`) ON DELETE CASCADE, CONSTRAINT `fk_jl_stage_transition_target` FOREIGN KEY (`target_stage_id`, `project_id`) REFERENCES `#__joomleague_project_stage` (`id`, `project_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_jl_stage_transition_distinct` CHECK (`source_stage_id` <> `target_stage_id`), CONSTRAINT `chk_jl_stage_transition_selector` CHECK (`selector_type` REGEXP '^[a-z][a-z0-9_]*$'), CONSTRAINT `chk_jl_stage_transition_carry` CHECK (`carry_over_mode` REGEXP '^[a-z][a-z0-9_]*$'), CONSTRAINT `chk_jl_stage_transition_seed` CHECK (`target_seed_start` IS NULL OR `target_seed_start` > 0), CONSTRAINT `chk_jl_stage_transition_published` CHECK (`published` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
